<script setup>import { reactive,ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../../stores/auth'; import AuthLayout from '../../layouts/AuthLayout.vue'; const router=useRouter(); const auth=useAuthStore(); const error=ref(''); const form=reactive({name:'',email:'',password:'',password_confirmation:''}); const submit=async()=>{try{error.value=''; await auth.register(form); router.push('/dashboard')}catch(e){error.value=e.response?.data?.message||'Ошибка регистрации'}}</script><template><AuthLayout><h1 class="mt-6 text-3xl font-bold">Регистрация</h1><form class="mt-6 space-y-4" @submit.prevent="submit"><input class="input" v-model="form.name" placeholder="Имя"><input class="input" v-model="form.email" placeholder="Email"><input class="input" v-model="form.password" type="password" placeholder="Пароль"><input class="input" v-model="form.password_confirmation" type="password" placeholder="Повторите пароль"><p v-if="error" class="text-sm text-red-600">{{ error }}</p><button class="btn-primary w-full">Создать аккаунт</button></form><router-link class="mt-5 block text-sm font-semibold" to="/login">Уже есть аккаунт?</router-link></AuthLayout></template>
